style.css:
/* General Tweaks */
body {
  background-color: #948d8d !important; /* Dark Mode Background */
  color: #f2a5a5 !important; /* Text Color */
}

/* Sidebar Customization */
div[role="region"] {
  background-color: #1e1e1e !important; /* Sidebar Background */
  border-right: 1px solid #333 !important; /* Sidebar Divider */
}

input[type="text"] {
  background-color: #2c2c2c !important; /* Search Bar Background */
  color: #eaeaea !important; /* Search Bar Text */
  border-radius: 10px !important;
}

div[aria-label="Chat list"] span {
  color: #eaeaea !important; /* Contact Name in Sidebar */
}

div[role="region"] div:hover {
  background-color: #333 !important; /* Sidebar Chat Background Hover */
  border-radius: 10px !important;
}

/* Chat Window */
div[role="main"] {
  background-color: #1a1a1a !important; /* Chat Background */
}

div[data-testid="message-in"], div[data-testid="message-out"] {
  border-radius: 20px !important; /* Rounded Chat Bubbles */
  padding: 8px 12px !important;
  font-size: 14px !important;
}

/* Incoming Messages */
div[data-testid="message-in"] {
  background-color: #2b2b2b !important; /* Incoming Bubble */
  color: #eaeaea !important; /* Text Color */
}

/* Outgoing Messages */
div[data-testid="message-out"] {
  background-color: #006d5b !important; /* Outgoing Bubble */
  color: #ffffff !important;
}

/* Header Tweaks */
header {
  background-color: #1e1e1e !important; /* Chat Header Background */
  border-bottom: 1px solid #333 !important;
}

header h1, header h2, header h3 {
  color: #eaeaea !important; /* Chat Header Name */
}

/* Emoji Panel */
div[aria-label="Emoji panel"] {
  background-color: #2c2c2c !important; /* Emoji Background */
}

div[aria-label="Emoji panel"] span {
  color: #eaeaea !important; /* Emoji Category Text */
}

/* Footer Section */
footer {
  background-color: #1e1e1e !important; /* Footer Background */
  border-top: 1px solid #333 !important;
}

footer input {
  background-color: #2c2c2c !important; /* Footer Input Field */
  border-radius: 10px !important;
  color: #eaeaea !important;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-thumb {
  background: #444 !important;
  border-radius: 10px;
}

::-webkit-scrollbar-track {
  background: #222 !important;
}
